#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/vectorflow/FrontendContainer"
cd "$WORKSPACE"
# detect typescript usage
IS_TS=0
if jq -e . >/dev/null 2>&1 <<'JQ' && false; then
  :
fi
# simple detection via package.json dependencies/devDependencies
IS_TS=$(node -e "const p=require('./package.json'); console.log(((p.dependencies&&p.dependencies.typescript)||(p.devDependencies&&p.devDependencies.typescript))?1:0);")
mkdir -p src
if [ "${IS_TS}" -eq 1 ]; then
  cat > src/setupTests.ts <<'EOF'
import '@testing-library/jest-dom';
EOF
  cat > src/Hello.test.tsx <<'EOF'
import React from 'react';
import { render, screen } from '@testing-library/react';
function Hello(): JSX.Element { return <div>hi</div> }
test('renders hello', ()=>{ render(<Hello/>); expect(screen.getByText('hi')).toBeInTheDocument(); });
EOF
else
  cat > src/setupTests.js <<'EOF'
import '@testing-library/jest-dom';
EOF
  cat > src/Hello.test.js <<'EOF'
import React from 'react';
import { render, screen } from '@testing-library/react';
function Hello(){ return <div>hi</div> }
test('renders hello', ()=>{ render(<Hello/>); expect(screen.getByText('hi')).toBeInTheDocument(); });
EOF
fi
export CI=true
# run tests using npm script to ensure project-local jest
npm test --silent -- --watchAll=false || (sleep 2 && npm test --silent -- --watchAll=false) || { echo 'Tests failed' >&2; exit 3; }

